from pathlib import Path
import hashlib
import json
import subprocess

ROOT = Path('/home/codex/.codex/worktrees/ec20/Proofs')
RESULTS = ROOT / 'Computability/BusyBeaver/Research/ZFC/results'

def sha(data):
    return hashlib.sha256(data).hexdigest()

def desc(path):
    path = Path(path)
    return {'path': str(path), 'sha256': sha(path.read_bytes())}

def write(path, data):
    assert not path.exists(), path
    path.write_text(json.dumps(data, indent=2) + '\n')
    print(json.dumps(desc(path)))

reviews = [
    (Path('/tmp/zfc-upstream-internal-interpretation-ec37dd933a/review.json'), '49dc43c9166fcb77fbdcffb45196749b8d6f4445bfe44bfb2cf9d13b9c596c33'),
    (Path('/tmp/zfc-upstream-internal-interpretation-ec37dd933a/review.md'), 'e632bda4ec500d76e179b3cf8cda8d337efa275b6d25c313209b99ab6c188b7c'),
    (Path('/tmp/zfc-r3-wf-route-review/review.json'), 'a88f8e34d05256e2acafbf0bd0c3e8351cb62fea5264f2cd391c7ed1a9421e9a'),
    (Path('/tmp/zfc-r3-wf-route-review/review.md'), 'b09ac97893229961c07532b41413dd310528a3f022ab36df94edbe882c08bc44'),
]
aliases, texts, current, historical = {}, {}, {}, []
plan = ROOT / 'Computability/BusyBeaver/Research/ZFC/pa_internalization.md'
plan_old_sha = '7d2bb584377c564a96adcd3bdf9fa03b7620d638f2b32df619e147838eeb310f'
plan_old = subprocess.check_output(['git', 'show', '1b247734ca3a7d990add9ae2b8524014da8fd583:' + str(plan.relative_to(ROOT))], cwd=ROOT)
assert sha(plan_old) == plan_old_sha

def validate(x):
    if isinstance(x, dict):
        if 'path' in x and 'sha256' in x:
            p = Path(x['path'])
            if p == plan and x['sha256'] == plan_old_sha:
                historical.append({'path': str(p), 'sha256': plan_old_sha, 'retrieved_from_commit': '1b247734ca3a7d990add9ae2b8524014da8fd583', 'reason': 'Plan updated after the source review; original exact bytes retained here.'})
            else:
                assert p.is_file() and sha(p.read_bytes()) == x['sha256'], x
                current[str(p)] = x['sha256']
        for v in x.values():
            validate(v)
    elif isinstance(x, list):
        for v in x:
            validate(v)

for p, h in reviews:
    b = p.read_bytes()
    assert sha(b) == h, p
    aliases[str(p)] = {'sha256': h, 'bytes': len(b)}
    texts[h] = b.decode()
    if p.suffix == '.json':
        validate(json.loads(b))
texts[plan_old_sha] = plan_old.decode()
aliases[str(plan) + '@1b247734ca3a7d990add9ae2b8524014da8fd583'] = {'sha256': plan_old_sha, 'bytes': len(plan_old)}
write(RESULTS / 'upstream-internal-interpretation-ec37dd933a-review.json', {
    'status': 'SOURCE_ONLY_INTERNAL_INTERPRETATION_AND_WF_ROUTE_REVIEW',
    'scope': 'Preserves both independent source reviews, the exact generic internal interpretation core, and the definable internally-well-founded quotient route. No fresh compiler or supplied checker execution. Fixed-formula quotation/Good and uniform all-internal axiom transport remain obligations.',
    'aliases': aliases, 'text_by_sha256': texts,
    'current_descriptor_checks': current, 'historical_descriptors': historical,
    'publication_preflight_history': 'An initial collector stopped before writing output when it treated the older plan descriptor as current. This successor verifies that descriptor against the exact historical Git blob and preserves its bytes explicitly.',
    'findings': [],
})

prep_path = Path('/tmp/zfc-routing245-binary-maintained-prepared/verification.json')
prep = json.loads(prep_path.read_text())
assert sha(prep_path.read_bytes()) == 'd330e584ad978a1d443fdf327feec0d43adb7737478b0c902222c7468ade926e'
assert prep['status'] == 'PREPARED_NOT_BUILT' and prep['prepare_only'] is True
assert prep['commands'] == prep['fresh_modules'] == []
assert not prep['source_overridden'] and not prep['audit_overridden']
assert not prep['compiler_version_query_performed']
assert not prep['dependency_build'] and not prep['downloads']
assert prep['before'] == prep['after'] and len(prep['before']) == 1726
assert prep['project_module_count'] == 851 and len(prep['reused_modules']) == 851
assert prep['exact_project_import_closure'] and prep['all_input_provider_postchecks']
assert prep['external_project_boundaries'] == [] and len(prep['toolchain_providers']) == 2
assert prep['expected_named_axiom_probes'] == prep['expected_callers'] == 11
assert prep['limits'] == {'threads': 1, 'memory_mebibytes': 4096, 'shared_wall_seconds': 120, 'proof_limits': 'Lean defaults'}
for p, h in prep['before'].items():
    assert sha(Path(p).read_bytes()) == h, p
for provider in prep['actual_first_providers']:
    p = Path(provider['actual_first'])
    assert str(p.resolve()) == provider['resolved'], provider
    assert sha(p.read_bytes()) == provider['sha256'], provider
for key in ['source', 'audit']:
    row = prep[key]
    assert sha(Path(row['snapshot']).read_bytes()) == row['sha256']
write(RESULTS / 'routing245-binary-maintained-preparation.json', {
    'status': 'ROOT_MAINTAINED_DEFAULT_PREPARATION_REVIEW_PASS',
    'preparation': desc(prep_path), 'inputs': 1726, 'projects': 851,
    'default_paths_used': True,
    'all_current_inputs_and_first_providers_checked': True,
    'commands': [], 'findings': [], 'record': prep,
})

packet = Path('/tmp/zfc-routing245-binary-publication')
peer_path = packet / 'independent-installed-defaults-review.json'
peer = json.loads(peer_path.read_text())
assert sha(peer_path.read_bytes()) == 'c304bc1816c83a0b0eca37b77517b87d1ed5ac129b33e29989f24002d9a76aae'
assert peer['findings'] == []
aliases, texts = {}, {}
for p in [peer_path, packet / 'map.json', packet / 'root-installation-review.json', packet / 'review_installed_defaults.py']:
    b = p.read_bytes(); h = sha(b)
    aliases[str(p)] = {'sha256': h, 'bytes': len(b)}
    texts[h] = b.decode()
write(RESULTS / 'routing245-binary-installed-review.json', {
    'status': 'PUBLISHED_ROUTING245_BINARY_INSTALLATION_AND_DEFAULTS_REVIEW',
    'peer_review': desc(peer_path), 'reviewer_role': peer['reviewer_role'],
    'aliases': aliases, 'text_by_sha256': texts, 'findings': [],
})

